sys_ux_client_script.script:
/**
* @param {Object} params
* @param {Object} params.api
* @param {Object} params.helpers
* @returns {string} A comma-separated list of short descriptions containing the keyword.
*/
function evaluateProperty({ api, helpers }) {
    console.log("🔍 Fetching SaaS Integration Data...");

    // Retrieve sys property data from Dynamic Sys Reader
    const saasData = api.data.dynamic_sys_reader_3.output;

    if (!saasData || typeof saasData !== "object") {
        console.warn("⚠️ No valid SaaS integration data found.");
        return "descriptionSTARTSWITHNo Data Available";
    }

    console.log("✅ Retrieved Data:", saasData);

    // Extract only the 'description' values from each integration
    const output = Object.keys(saasData).map(key => saasData[key].description);

    console.log("🔹 Extracted Descriptions:", output);

    if (output.length > 0) {
        // Create query string for filtering
        const query = output.map(value => `descriptionSTARTSWITH${value.split(" ").slice(0, 3).join(" ")}`).join('^OR');

        console.log("🛠️ Generated Query:", query);
        return query;
    }

    return "descriptionSTARTSWITHNo Matching Data";
}
